import {assistantEndpoint} from './ai-config.js?v=19';
export class LabAssistant{
 constructor({getContext,capture,endpoint=assistantEndpoint,document=globalThis.document,fetcher=globalThis.fetch}={}){
  Object.assign(this,{document,getContext,capture,endpoint,fetcher,threads:new Map(),drafts:new Map(),busy:false,attachments:[],preparing:0});
  this.root=document.createElement('aside');this.root.id='aiAssistant';this.root.className='ai-assistant';this.root.hidden=true;this.root.setAttribute('aria-labelledby','aiTitle');
  this.root.innerHTML='<div class="ai-head"><h2 id="aiTitle">Trợ lý Vật lí</h2><div><button type="button" data-ai="expand" aria-label="Mở rộng trợ lý" aria-pressed="false">↗</button><button type="button" data-ai="close" aria-label="Đóng trợ lý">×</button></div></div><p class="ai-status" role="status" aria-live="polite"></p><div class="ai-messages" role="log" aria-label="Hội thoại"></div><form class="ai-compose"><label for="aiQuestion">Câu hỏi của bạn</label><textarea id="aiQuestion" maxlength="6000" placeholder="Hỏi về hiện tượng, số liệu hoặc gửi ảnh…"></textarea><div class="ai-attachments" aria-label="Ảnh sắp gửi"></div><div class="ai-tools"><button type="button" data-ai="attach">＋ Thêm ảnh</button><button type="button" data-ai="capture">Chụp mô hình</button><input type="file" id="aiImage" accept="image/png,image/jpeg,image/webp" multiple hidden></div><label class="ai-consent"><input type="checkbox" id="aiContext">Gửi kèm thông số và 12 dòng đo gần nhất</label><details><summary>Xem dữ liệu gửi kèm</summary><pre class="ai-context"></pre><p>Ảnh và dữ liệu chỉ gửi tới OpenAI khi bạn nhấn Gửi. Hội thoại được giữ trong bộ nhớ của trang, không lưu sau khi tải lại.</p></details><div class="ai-actions"><button type="button" data-ai="clear">Hội thoại mới</button><button type="button" data-ai="cancel" hidden>Dừng</button><button type="submit">Gửi ↑</button></div></form>';
  document.body.append(this.root);this.q=s=>this.root.querySelector(s);this.status=this.q('.ai-status');this.form=this.q('form');this.input=this.q('textarea');this.submit=this.q('[type=submit]');
  this.openButton=document.querySelector('#openAssistant');this.openButton?.addEventListener('click',()=>this.open());
  this.q('[data-ai=close]').addEventListener('click',()=>this.close());this.q('[data-ai=expand]').addEventListener('click',e=>{const wide=this.root.classList.toggle('ai-wide');e.currentTarget.setAttribute('aria-pressed',String(wide));e.currentTarget.setAttribute('aria-label',wide?'Thu gọn trợ lý':'Mở rộng trợ lý');});
  this.q('[data-ai=cancel]').addEventListener('click',()=>this.controller?.abort());this.q('[data-ai=clear]').addEventListener('click',()=>{if(this.busy)return;this.threads.delete(this.key());this.input.value='';this.attachments=[];this.render();});
  this.q('[data-ai=attach]').addEventListener('click',()=>this.q('#aiImage').click());this.q('#aiImage').addEventListener('change',async e=>{await this.addFiles([...e.target.files]);e.target.value='';});
  this.q('[data-ai=capture]').addEventListener('click',()=>this.captureModel());
  this.input.addEventListener('paste',e=>{const files=[...(e.clipboardData?.files||[])];if(files.length){e.preventDefault();this.addFiles(files);}});
  this.root.addEventListener('dragover',e=>{if(e.dataTransfer?.types?.includes('Files'))e.preventDefault();});this.root.addEventListener('drop',e=>{if(e.dataTransfer?.files?.length){e.preventDefault();this.addFiles([...e.dataTransfer.files]);}});
  this.form.addEventListener('submit',e=>{e.preventDefault();this.send();});this.input.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();this.send();}});this.root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();this.close();}});this.render();
 }
 key(){return this.getContext?.()?.id||'library';}
 thread(key=this.key()){if(!this.threads.has(key))this.threads.set(key,[]);return this.threads.get(key);}
 refreshContext(){if(this.root.hidden)return;if(this.currentKey!==this.key())this.render();else this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{},null,2);this.q('[data-ai=capture]').disabled=!this.capture||this.key()==='library'||this.busy;}
 open(){this.root.hidden=false;this.openButton?.setAttribute('aria-expanded','true');this.render();this.input.focus();}
 close(){this.root.hidden=true;this.openButton?.setAttribute('aria-expanded','false');this.openButton?.focus();}
 render(){const key=this.key();if(this.currentKey&&this.currentKey!==key){this.drafts.set(this.currentKey,{text:this.input.value,attachments:this.attachments});const draft=this.drafts.get(key);this.input.value=draft?.text||'';this.attachments=draft?.attachments||[];}this.currentKey=key;
  const list=this.q('.ai-messages');list.replaceChildren();for(const message of this.thread()){const el=this.document.createElement('div');el.className='ai-message';el.dataset.role=message.role;const label=this.document.createElement('b');label.textContent=message.role==='user'?'Bạn':'Trợ lý AI';el.append(label,this.document.createTextNode(message.content));for(const src of message.images||[]){const img=this.document.createElement('img');img.src=src;img.alt='Ảnh đã gửi';el.append(img);}list.append(el);}if(!this.thread().length){const el=this.document.createElement('p');el.className='ai-empty';el.textContent='Gửi câu hỏi hoặc ảnh. Bạn có thể hỏi tiếp để hiểu rõ cách giải.';list.append(el);}list.scrollTop=list.scrollHeight;
  const previews=this.q('.ai-attachments');previews.replaceChildren();this.attachments.forEach((attachment,index)=>{const wrap=this.document.createElement('div'),img=this.document.createElement('img'),remove=this.document.createElement('button');img.src=attachment.url;img.alt=attachment.name;remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Xóa ảnh '+attachment.name);remove.disabled=this.busy;remove.addEventListener('click',()=>{this.attachments.splice(index,1);this.render();});wrap.append(img,remove);previews.append(wrap);});
  this.q('.ai-context').textContent=JSON.stringify(this.getContext?.()||{},null,2);this.submit.disabled=this.busy||this.preparing>0||!this.endpoint;this.q('[data-ai=cancel]').hidden=!this.busy;for(const name of ['clear','attach'])this.q('[data-ai='+name+']').disabled=this.busy||this.preparing>0;this.q('[data-ai=capture]').disabled=this.busy||this.preparing>0||!this.capture||key==='library';this.status.textContent=this.preparing?'Đang chuẩn bị ảnh…':this.busy?'Đang phân tích và trả lời…':this.endpoint?'AI có thể nhầm. Hãy đối chiếu công thức và số liệu.':'Trợ lý đang chờ hoàn tất kết nối máy chủ.';
 }
 async compress(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Chọn ảnh PNG, JPEG hoặc WebP.');if(file.size>12000000)throw Error('Ảnh tối đa 12 MB.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>32000000)throw Error('Ảnh quá lớn. Hãy cắt vùng cần hỏi.');const canvas=this.document.createElement('canvas'),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const url=canvas.toDataURL('image/jpeg',.82);if(url.length>1900000)throw Error('Ảnh vẫn quá lớn. Hãy cắt vùng cần hỏi.');return url;}finally{bitmap.close();}}
 async addFiles(files){if(this.busy||this.preparing)return;const key=this.key();this.preparing++;this.render();let error='';try{for(const file of files){if(this.attachments.length>=2)throw Error('Mỗi câu hỏi gửi tối đa 2 ảnh.');const url=await this.compress(file);if(this.key()!==key)throw Error('Bạn đã chuyển bài. Hãy thêm ảnh vào bài đang mở.');this.attachments.push({url,name:file.name||'Ảnh dán'});}}catch(e){error=e.message||'Không đọc được ảnh.';}finally{this.preparing--;this.render();if(error)this.status.textContent=error;}}
 async captureModel(){if(this.busy||this.preparing||!this.capture)return;this.preparing++;this.render();let error='';try{if(this.attachments.length>=2)throw Error('Mỗi câu hỏi gửi tối đa 2 ảnh.');const key=this.key(),result=await this.capture();if(!result?.image)throw Error('Chưa có mô hình để chụp.');const blob=await (await fetch(result.image)).blob(),url=await this.compress(blob);if(this.key()!==key)throw Error('Bạn đã chuyển bài. Hãy chụp lại mô hình.');this.attachments.push({url,name:'Mô hình '+(result.context?.title||''),context:result.context});this.q('#aiContext').checked=true;}catch(e){error=e.message||'Không chụp được mô hình.';}finally{this.preparing--;this.render();this.status.textContent=error||'Đã thêm ảnh mô hình và thông số tại thời điểm chụp. Bấm Gửi để hỏi.';}}
 async send(){const question=this.input.value.trim();if((!question&&!this.attachments.length)||this.busy||this.preparing||!this.endpoint)return;const key=this.key(),thread=this.thread(key),attachments=[...this.attachments],images=attachments.map(a=>a.url),capture=attachments.find(a=>a.context),context=this.q('#aiContext').checked?(capture?{...capture.context,snapshot:true}:this.getContext?.()||null):null;
  const history=thread.slice(-10).map(m=>({role:m.role,content:m.content,images:[...(m.images||[])]}));let kept=images.length;for(let i=history.length-1;i>=0;i--){history[i].images=history[i].images.slice(0,Math.max(0,4-kept));kept+=history[i].images.length;}while(JSON.stringify({question,history,context,images}).length>4400000&&history.length)history.shift();
  this.busy=true;this.controller=new AbortController();this.render();const controller=this.controller,timeout=setTimeout(()=>controller.abort(),60000);
  try{const response=await this.fetcher(this.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history,context,images}),signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});let data;try{data=await response.json();}catch{throw Error('Máy chủ chưa sẵn sàng hoặc yêu cầu đăng nhập.');}if(!response.ok)throw Error(data.error||'Chưa gửi được câu hỏi.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('Máy chủ chưa trả về câu trả lời.');thread.push({role:'user',content:question||'Giải thích ảnh thí nghiệm.',images},{role:'assistant',content:data.answer.slice(0,16000)});if(thread.length>40)thread.splice(0,thread.length-40);for(const old of thread.slice(0,-10))delete old.images;if(this.key()===key){this.input.value='';this.attachments=[];}else this.drafts.delete(key);this.busy=false;this.render();if(this.key()!==key)this.status.textContent='Đã lưu câu trả lời trong hội thoại của bài trước.';
  }catch(error){this.busy=false;this.render();this.status.textContent=error.name==='AbortError'?'Đã dừng chờ phản hồi. Câu hỏi và ảnh vẫn được giữ.':error.message||'Không kết nối được trợ lý. Kiểm tra mạng và thử lại.';}
  finally{clearTimeout(timeout);this.controller=null;}
 }
}
